  async function overviewPageV2() {
    const c=document.querySelector('#content');
    c.innerHTML=head('Operations Command Center','Live capacity, demand risk, and recommended driver-routing actions.',`<button class="btn" id="export">Export zone data</button><button class="btn primary" id="reroute"><span class="material-symbols-outlined" style="font-size:16px;vertical-align:middle">alt_route</span> Smart reroute</button>`)+`<div class="grid kpis" id="kpis"></div><div class="grid section-grid" style="grid-template-columns:minmax(0,1.35fr) minmax(360px,.85fr);margin-bottom:15px">${card('Demand outlook · actual vs forecast','<div class="card-sub" id="forecastMeta">Latest 24-hour model window</div><div class="chart" id="overviewTrend"></div>')}${card('Priority zones','<div class="card-sub">Ranked by current capacity pressure</div><div id="leader"></div>')}</div><div class="grid cols2">${card('Highest utilization','<div class="card-sub">Top zones · percentage of capacity</div><div class="chart" id="capacityChart"></div>')}${card('Best availability','<div class="card-sub">Where drivers can be redirected now</div><div class="chart" id="zoneBars"></div>')}</div>`;
    try {
      const [d,p]=await Promise.all([api('/api/overview'),api(`/api/predictions?zone=${state.selectedZone}`)]),k=d.kpis;
      const kpiData=[['local_parking','Network utilization',`${fmt(k.utilization)}%`,`${fmt(k.occupied)} of ${fmt(k.capacity)} bays occupied`],['directions_car','Available now',fmt(k.available),'Across the monitored network'],['location_city','Reporting zones',fmt(k.zones),state.selectedZone==='ALL'?'Mumbai network':state.selectedZone],['speed','Event velocity',`${fmt(k.events_per_second)}/s`,d.updated_at?`Updated ${new Date(d.updated_at).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}`:'Waiting for events']];
      document.querySelector('#kpis').innerHTML=kpiData.map(x=>`<section class="card"><span class="material-symbols-outlined kpi-icon">${x[0]}</span><div class="kpi-label">${x[1]}</div><div class="kpi-value">${x[2]}</div><div class="kpi-foot">${x[3]}</div></section>`).join('');
      const visible=state.selectedZone==='ALL'?d.zones:d.zones?d.zones.filter(z=>z.zone_id===state.selectedZone):[];
      document.querySelector('#leader').innerHTML=visible.slice(0,7).map((z,i)=>`<button class="metric-row" data-zone="${z.zone_id}" style="width:100%;border:0;background:transparent;color:inherit;text-align:left"><span class="metric-name"><b>${i+1}. ${z.zone_id} · ${esc(z.zone_name)}</b><span>${z.occupancy} occupied · ${z.available} free · ${z.capacity} total</span></span><span style="width:110px"><span class="progress"><i style="width:${Math.min(100,z.utilization)}%;background:${z.risk==='HIGH'?'var(--red)':z.risk==='MEDIUM'?'var(--amber)':'var(--teal)'}"></i></span></span><span class="risk-value ${z.risk}">${fmt(z.utilization)}%</span></button>`).join('')||'<div class="empty">No zone matches this filter.</div>';
      document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>{state.selectedZone=b.dataset.zone;document.querySelector('#globalZone').value=state.selectedZone;render()});
      let points=p.series;
      if(state.selectedZone==='ALL'){
        const grouped=new Map();points.forEach(x=>{const key=x.timestamp,row=grouped.get(key)||{timestamp:key,current_occupancy:0,predicted_occupancy:0};row.current_occupancy+=Number(x.current_occupancy||0);row.predicted_occupancy+=Number(x.predicted_occupancy||0);grouped.set(key,row)});points=[...grouped.values()].sort((a,b)=>String(a.timestamp).localeCompare(String(b.timestamp))).slice(-120);
        document.querySelector('#forecastMeta').textContent='Network-wide occupancy, aggregated across all zones';
      } else points=points.slice(-120);
      svgLine(document.querySelector('#overviewTrend'),[{name:'Observed',values:points.map(x=>x.current_occupancy),color:'#20d9e9'},{name:'RF forecast',values:points.map(x=>x.predicted_occupancy),color:'#21d3a2'}]);
      const pressure=[...visible].sort((a,b)=>b.utilization-a.utilization).slice(0,10),available=[...visible].sort((a,b)=>b.available-a.available).slice(0,10);
      svgHBars(document.querySelector('#capacityChart'),pressure.map(z=>z.zone_id),pressure.map(z=>z.utilization),pressure.map(z=>z.risk==='HIGH'?'#ff6577':z.risk==='MEDIUM'?'#f6b84a':'#21d3a2'));
      svgHBars(document.querySelector('#zoneBars'),available.map(z=>z.zone_id),available.map(z=>z.available),available.map(()=>'#21d3a2'));
      document.querySelector('#export').onclick=()=>download('/api/export?kind=zones&format=csv');
      document.querySelector('#reroute').onclick=()=>{const best=[...d.zones].filter(z=>z.available>0&&z.risk!=='HIGH').sort((a,b)=>b.available-a.available).slice(0,3);modal('Recommended diversion plan',best.map((z,i)=>`<div class="insight"><strong>${i+1}. ${z.zone_id} · ${esc(z.zone_name)}</strong><span>${z.available} bays open · ${z.utilization}% utilized. Send overflow traffic here.</span></div>`).join(''))};
    } catch(e){error(c,e)}
  }

