    const presets=document.createElement('div');presets.className='toolbar';presets.innerHTML='<button class="btn" data-scenario="commute">Morning commute</button><button class="btn" data-scenario="rain">Heavy rain</button><button class="btn" data-scenario="weekend">Weekend event</button>';panel.querySelector('.card-head').after(presets);
